const raw = $input.first().json;
const body = raw.body || raw;
let requestType = 'initial';

if (body.answers && body.domain_model_b64) {
  requestType = 'answers';
} else if (body.file_name) {
  requestType = 'file';
} else if (body.mode === 'local') {
  requestType = 'local';
} else if (body.mode === 'a2a') {
  requestType = 'a2a';
} else if (body.domain_model) {
  requestType = 'file';
}

return [{ json: { ...body, requestType } }];

