const input = $input.first().json;
let domain_model, iteration, max_iterations, session_id, previous_answers;

// Check if this is the 'answers' path (loop iteration)
if (input.domain_model_b64) {
  // Decode base64 domain model from form
  const decoded = Buffer.from(input.domain_model_b64, 'base64').toString('utf-8');
  domain_model = JSON.parse(decoded);
  iteration = parseInt(input.iteration) || 0;
  max_iterations = parseInt(input.max_iterations) || 5;
  session_id = input.session_id || new Date().toISOString();
  previous_answers = input.answers || {};
} else if (input.domain_model) {
  // Direct A2A submission with domain_model in body
  domain_model = typeof input.domain_model === 'string' ? JSON.parse(input.domain_model) : input.domain_model;
  iteration = 0;
  max_iterations = 5;
  session_id = new Date().toISOString();
  previous_answers = {};
} else {
  // File loaded via HTTP - the entire response IS the domain model
  domain_model = input;
  iteration = 0;
  max_iterations = 5;
  session_id = new Date().toISOString();
  previous_answers = {};
}

return [{
  json: {
    domain_model: JSON.stringify(domain_model),
    iteration,
    max_iterations,
    session_id,
    previous_answers: JSON.stringify(previous_answers),
    use_llm: true,
    apply_auto_fixes: true
  }
}];

