const apiResult = $input.first().json;
const prepData = $('Prepara Dati').first().json;

const questions = apiResult.follow_up_questions || [];
const refinedModel = apiResult.refined_model || {};
const domainModelStr = Object.keys(refinedModel).length > 0 ? JSON.stringify(refinedModel) : prepData.domain_model;
const domainModelB64 = Buffer.from(domainModelStr).toString('base64');

// On first iteration, use LLM-suggested max_iterations from API; otherwise keep existing
const maxIter = (prepData.iteration === 0 && apiResult.suggested_max_iterations)
  ? apiResult.suggested_max_iterations
  : prepData.max_iterations;

// Pre-render questions HTML
let qHtml = '';
qHtml += '<input type="hidden" name="session_id" value="' + prepData.session_id + '">';
qHtml += '<input type="hidden" name="iteration" value="' + (prepData.iteration + 1) + '">';
qHtml += '<input type="hidden" name="max_iterations" value="' + maxIter + '">';
qHtml += '<input type="hidden" id="domain_model_b64" name="domain_model_b64" value="' + domainModelB64 + '">';
qHtml += '<input type="hidden" id="question_count" value="' + questions.length + '">';
questions.forEach((q, i) => {
  const sev = q.severity || 'MEDIUM';
  qHtml += '<div class="q-block">';
  qHtml += '<div class="q-num">' + (i+1) + '</div>';
  qHtml += '<div class="q-label">' + (q.question || '') + ' <span class="severity sev-' + sev + '">' + sev + '</span></div>';
  if (q.context) qHtml += '<div class="context-info">' + q.context + '</div>';
  if (q.suggested_answers && q.suggested_answers.length > 0) {
    qHtml += '<div class="options-group" data-q="' + i + '">';
    q.suggested_answers.forEach((sa) => {
      const saEsc = String(sa).replace(/"/g, '&quot;');
      qHtml += '<label class="option-label"><input type="radio" name="q' + i + '" value="' + saEsc + '"> ' + sa + '</label>';
    });
    qHtml += '<label class="option-label"><input type="radio" name="q' + i + '" value="__custom__"> Altro (testo libero)</label>';
    qHtml += '</div>';
    qHtml += '<textarea class="custom-area" name="q' + i + '_custom" placeholder="Scrivi la tua risposta personalizzata..."></textarea>';
  } else {
    qHtml += '<textarea class="freetext" name="q' + i + '" placeholder="Scrivi la tua risposta..." required></textarea>';
  }
  qHtml += '</div>';
});
if (questions.length === 0) {
  qHtml += '<p style="text-align:center;color:#6b7280;padding:20px">Nessuna domanda generata. Il modello potrebbe necessitare di una revisione manuale.</p>';
}

return [{
  json: {
    session_id: prepData.session_id,
    iteration: prepData.iteration,
    max_iterations: maxIter,
    domain_model: prepData.domain_model,
    domain_model_b64: domainModelB64,
    status: apiResult.status,
    follow_up_questions: JSON.stringify(questions),
    refined_model: JSON.stringify(refinedModel),
    summary: JSON.stringify(apiResult.summary || {}),
    semantic_issues: JSON.stringify(apiResult.semantic_issues || []),
    conflict_issues: JSON.stringify(apiResult.conflict_issues || []),
    questions_html: qHtml
  }
}];

