    textarea.freetext{width:100%;padding:14px;border:2px solid #d1d5db;border-radius:10px;font-size:14px;font-family:inherit;resize:vertical;min-height:100px;transition:all .3s}
    textarea.freetext:focus{outline:none;border-color:#667eea;box-shadow:0 0 0 3px rgba(102,126,234,0.1)}
    .submit-btn{width:100%;background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;border:none;padding:18px;border-radius:12px;font-size:16px;font-weight:700;cursor:pointer;transition:all .3s;margin-top:24px;box-shadow:0 8px 20px rgba(102,126,234,0.3)}
    .submit-btn:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(102,126,234,0.4)}
    .submit-btn:disabled{opacity:.6;cursor:not-allowed;transform:none}
    .footer{text-align:center;padding:20px;color:#9ca3af;font-size:12px;border-top:1px solid #e5e7eb;background:#f9fafb}
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Agent 2 - Validazione DDD</h1>
      <p>Rispondi alle domande per raffinare il modello collaborativamente</p>
    </div>
    <div class="content">
      <div class="iter-badge">Iterazione {{ $json.iteration + 1 }} di {{ $json.max_iterations }}</div>
      <div class="summary">
        <h3>Riepilogo Problemi</h3>
        <div class="summary-grid">
          <div class="summary-item"><strong>{{ JSON.parse($json.summary).total_issues || 0 }}</strong> Problemi totali</div>
          <div class="summary-item"><strong>{{ JSON.parse($json.summary).entity_overlaps || 0 }}</strong> Entity overlaps</div>
          <div class="summary-item"><strong>{{ JSON.parse($json.summary).requirement_conflicts || 0 }}</strong> Conflitti requisiti</div>
          <div class="summary-item"><strong>{{ JSON.parse($json.summary).auto_fixed || 0 }}</strong> Auto-corretti</div>
        </div>
      </div>
      <form id="answersForm">
        {{ $json.questions_html }}
        <button type="submit" class="submit-btn" id="submitBtn">Invia Risposte e Continua Raffinamento</button>
      </form>
    </div>
    <div class="footer">Agent 2 - Consistency &amp; Conflict Analyzer | Powered by n8n + Ollama + Llama3</div>
  </div>
  <script>
    // Radio button selection highlighting and custom textarea toggle
    document.querySelectorAll('.option-label input[type=radio]').forEach(radio => {
      radio.addEventListener('change', function() {
        const group = this.closest('.options-group');
        group.querySelectorAll('.option-label').forEach(l => l.classList.remove('selected'));
        this.closest('.option-label').classList.add('selected');
        const customArea = group.nextElementSibling;
        if (customArea && customArea.classList.contains('custom-area')) {
          if (this.value === '__custom__') {
            customArea.classList.add('visible');
            customArea.focus();
          } else {
            customArea.classList.remove('visible');
          }
        }
      });
    });

    // Form submission
    document.getElementById('answersForm').addEventListener('submit', async function(e) {
      e.preventDefault();
      const form = this;
      const btn = document.getElementById('submitBtn');
      const questionCount = parseInt(document.getElementById('question_count').value);

      // Collect answers
      const answers = {};
      for (let i = 0; i < questionCount; i++) {
        const radio = form.querySelector('input[name="q' + i + '"]:checked');
        if (radio) {
          if (radio.value === '__custom__') {
            const customVal = form.querySelector('textarea[name="q' + i + '_custom"]').value.trim();
            if (!customVal) { alert('Inserisci la risposta personalizzata per la domanda ' + (i+1)); return; }
            answers['q' + i] = customVal;
          } else {
            answers['q' + i] = radio.value;
          }
        } else {
          const textarea = form.querySelector('textarea[name="q' + i + '"]');
          if (textarea) {
            if (!textarea.value.trim()) { alert('Rispondi alla domanda ' + (i+1)); return; }
            answers['q' + i] = textarea.value.trim();
          }
        }
      }

      // Disable form
      btn.textContent = 'Elaborazione in corso...';
      btn.disabled = true;
      form.querySelectorAll('input,textarea').forEach(el => el.disabled = true);

      const data = {
        session_id: form.querySelector('[name=session_id]').value,
        iteration: parseInt(form.querySelector('[name=iteration]').value),
        max_iterations: parseInt(form.querySelector('[name=max_iterations]').value),
        domain_model_b64: form.querySelector('[name=domain_model_b64]').value,
        answers: answers
      };

      try {
        const res = await fetch(window.location.href.replace('agent2-start', 'agent2-submit'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data)
        });
        if (res.ok) {
          document.open();
          document.write(await res.text());
          document.close();
        } else {
          throw new Error('HTTP ' + res.status);
        }
      } catch(err) {
        alert('Errore: ' + err.message);
        btn.textContent = 'Invia Risposte e Continua Raffinamento';
        btn.disabled = false;
        form.querySelectorAll('input,textarea').forEach(el => el.disabled = false);
      }
    });
  </script>
</body>
</html>

